// packages/database/src/db/schema/snippet.ts
// Drizzle table: snippet (generated by scripts/split-schema.ts)

import { createId } from '@paralleldrive/cuid2'
import {
  type AnyPgColumn,
  boolean,
  index,
  integer,
  pgTable,
  sql,
  text,
  timestamp,
  uniqueIndex,
} from './_shared'
import { Organization } from './organization'
import { SnippetFolder } from './snippet-folder'
import { User } from './user'

/** Drizzle table for snippet */
export const Snippet = pgTable(
  'Snippet',
  {
    id: text()
      .$defaultFn(() => createId())
      .primaryKey()
      .notNull(),
    title: text().notNull(),
    content: text().notNull(),
    contentHtml: text(),
    description: text(),
    createdAt: timestamp({ precision: 3 }).defaultNow().notNull(),
    updatedAt: timestamp({ precision: 3 }).notNull(),
    isDeleted: boolean().default(false).notNull(),
    folderId: text().references((): AnyPgColumn => SnippetFolder.id, { onUpdate: 'cascade' }),
    organizationId: text()
      .notNull()
      .references((): AnyPgColumn => Organization.id, { onUpdate: 'cascade', onDelete: 'cascade' }),
    createdById: text()
      .notNull()
      .references((): AnyPgColumn => User.id, { onUpdate: 'cascade', onDelete: 'cascade' }),
    // `sharingType` dropped (plan 36 §7.2) — `snippet` is an
    // `INSTANCE_ACCESS_RESOURCES` key now, so who-can-see-this is `ResourceAccess`
    // rows and nothing else (§0.3). The legacy column's `GROUPS` value already
    // meant "check ResourceAccess"; the other two are converted by the inline
    // backfill in this column's own drop migration plus DataMigration 056.
    // `isFavorite` dropped: it was one boolean on the SHARED row, writable only
    // through `updateSnippet` (`edit`), so a `view` member could not star at all
    // and anyone with `edit` starred it for the whole org. Favouriting is
    // per-user `Favorite` rows (`targetType: 'SNIPPET'`) like every other
    // favouritable resource — the same move plan 36 §12.2 made for a signature's
    // "default".
    usageCount: integer().default(0).notNull(),
    /** System-seeded snippet marker (e.g. 'quote_email' | 'invoice_email' —
     *  `SnippetSystemType` in `@auxx/database/enums`). NULL for user-created
     *  snippets. Read-only in v1 — see snippet-mutations.ts guards. */
    systemType: text(),
  },
  (table) => [
    index('Snippet_createdById_idx').using('btree', table.createdById.asc().nullsLast()),
    index('Snippet_folderId_idx').using('btree', table.folderId.asc().nullsLast()),
    index('Snippet_organizationId_idx').using('btree', table.organizationId.asc().nullsLast()),
    index('Snippet_systemType_idx').using('btree', table.systemType.asc().nullsLast()),
    // One system snippet per (systemType, organizationId) — partial + NULL-safe so
    // regular user snippets (systemType NULL) are unconstrained. Mirrors
    // EntityDefinition_source_key (entity-definition.ts:106-116).
    uniqueIndex('Snippet_systemType_organizationId_key')
      .using('btree', table.systemType.asc().nullsLast(), table.organizationId.asc().nullsLast())
      .where(sql`${table.systemType} IS NOT NULL AND ${table.isDeleted} = false`),
  ]
)
